import random
import time
import requests

HEADERS = {
    "User-Agent": "Mozilla/5.0 (compatible; CodeReviseBot/1.0; +https://example.com/bot)",
    "Accept-Language": "en-US,en;q=0.9",
}

def polite_get(session, url, max_tries=4):
    for attempt in range(1, max_tries + 1):
        time.sleep(random.uniform(1.0, 2.5))            # jitter between requests
        try:
            r = session.get(url, headers=HEADERS, timeout=15)
        except requests.RequestException as exc:
            print("network error:", exc)
        else:
            if r.status_code == 200:
                return r
            if r.status_code in (429, 503):
                wait = int(r.headers.get("Retry-After", 2 ** attempt * 5))
                print(f"throttled, sleeping {wait}s")
                time.sleep(wait)
                continue
            r.raise_for_status()
        time.sleep(2 ** attempt)
    raise RuntimeError(f"gave up on {url}")

with requests.Session() as s:
    page = polite_get(s, "https://quotes.toscrape.com/")
    print(page.status_code)
